import{_ as a,o as t,c as o,aQ as r}from"./chunks/framework.cDvftfeu.js";const u=JSON.parse('{"title":"MCPサービス","description":"Ham MCPサービス紹介 — MCPプロトコルでHamの機能をAIアシスタントに接続。","frontmatter":{"description":"Ham MCPサービス紹介 — MCPプロトコルでHamの機能をAIアシスタントに接続。","next":{"text":"設定ガイド","link":"/ja/guide/mcp/config"}},"headers":[],"relativePath":"ja/guide/mcp/index.md","filePath":"ja/guide/mcp/index.md","lastUpdated":1779798458000}'),l={name:"ja/guide/mcp/index.md"};function i(n,e,c,s,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="mcpサービス" tabindex="-1">MCPサービス <a class="header-anchor" href="#mcpサービス" aria-label="Permalink to &quot;MCPサービス&quot;">​</a></h1><p>HamはMCP（Model Context Protocol）サービスを提供しており、MCP対応のAIアシスタント（Claude Desktop、Cursorなど）からHamのキャンパスデータと機能にアクセスできます。</p><h2 id="mcpとは" tabindex="-1">MCPとは？ <a class="header-anchor" href="#mcpとは" aria-label="Permalink to &quot;MCPとは？&quot;">​</a></h2><p>MCP（<a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a>）は、AIアプリケーションが外部データソースやツールに安全に接続できるようにするオープンプロトコルです。HamのMCPサービスを使うと、AIアシスタントで次のことができます：</p><ul><li>コース情報と成績の照会</li><li>個人情報の閲覧</li></ul><h2 id="サービスurl" tabindex="-1">サービスURL <a class="header-anchor" href="#サービスurl" aria-label="Permalink to &quot;サービスURL&quot;">​</a></h2><p>Ham MCPサービスは <strong>Streamable HTTP</strong> トランスポートを使用します：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mcp.ham.nowcent.cn/mcp</span></span></code></pre></div><h2 id="認証" tabindex="-1">認証 <a class="header-anchor" href="#認証" aria-label="Permalink to &quot;認証&quot;">​</a></h2><p>Ham MCPサービスは2種類の認証方式をサポートします：</p><ul><li><strong>OAuth動的登録（推奨）</strong>：クライアントが初回接続時に登録と認可を自動で完了します。API Keyを手動で発行する必要はなく、MCPのOAuthに対応した最新クライアント（Claude Desktop、Cursor、ChatGPT、Codexなど）に最適です。</li><li><strong>API Key</strong>：HamコンソールでAPI Keyを手動生成し、<code>Authorization: Bearer &lt;API_KEY&gt;</code> リクエストヘッダーで認証する方式。OAuth動的登録に対応していないクライアントや、長期固定の認証情報が必要な場合に利用します。</li></ul><h3 id="oauth動的登録-推奨" tabindex="-1">OAuth動的登録（推奨） <a class="header-anchor" href="#oauth動的登録-推奨" aria-label="Permalink to &quot;OAuth動的登録（推奨）&quot;">​</a></h3><p>Ham MCPサービスは <a href="https://modelcontextprotocol.io/specification/draft/basic/authorization" target="_blank" rel="noreferrer">MCP Authorization 仕様</a> に準拠し、<a href="https://datatracker.ietf.org/doc/html/rfc7591" target="_blank" rel="noreferrer">OAuth 2.0 動的クライアント登録（RFC 7591）</a> と <a href="https://datatracker.ietf.org/doc/html/rfc9728" target="_blank" rel="noreferrer">Protected Resource Metadata（RFC 9728）</a> を実装しています。</p><p>接続フローはクライアントが自動で処理します：</p><ol><li>クライアントがサービスURLへアクセスし、<code>401 Unauthorized</code> を受け取る</li><li><code>/.well-known/oauth-protected-resource</code> から認可サーバーをディスカバリ</li><li>動的登録エンドポイントへ自動登録し、<code>client_id</code> を取得</li><li>ブラウザが Ham 認可ページに遷移、ログインと同意の後にクライアントへ戻る</li><li>クライアントがアクセストークンを取得し、以降のリクエストへ自動付与（手動設定不要）</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>動的登録を利用する場合、クライアントにサービスURL <code>https://mcp.ham.nowcent.cn/mcp</code> を入力するだけで、それ以外の手順は自動で完了します。</p></div><h3 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h3><p>クライアントがOAuth動的登録に非対応の場合や、長期固定の認証情報を使用したい場合は、HamコンソールでAPI Keyを生成して手動で設定します。</p><h4 id="api-keyの取得" tabindex="-1">API Keyの取得 <a class="header-anchor" href="#api-keyの取得" aria-label="Permalink to &quot;API Keyの取得&quot;">​</a></h4><ol><li><a href="https://ham.nowcent.cn/console/tokens" target="_blank" rel="noreferrer">Hamコンソール - API Keys</a>にアクセス</li><li>「API Keyを作成」をクリック</li><li>API Keyに説明を追加（例：「Claude Desktop」）して管理しやすくする</li><li>生成されたAPI Keyをコピー（<strong>一度だけ表示されるので安全に保管してください</strong>）</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>API Keyを他人と共有しないでください。API Keyはアカウントの認証情報と同等であり、漏洩すると個人情報への不正アクセスされる可能性があります。</p></div>',21)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
